import os
import subprocess
import glob
import time
import sys

CONFIG_DIR = "configs"
TRAIN_SCRIPT = "alt_main.py" 
def run_night_shift():
    # 1. Gather all YAML configuration files generated by your grid search
    config_files = glob.glob(os.path.join(CONFIG_DIR, "*.yaml"))
    
    # Sort them so they run in order (e.g., exp_1.yaml, exp_2.yaml)
    # Using a custom key to sort by the integer value in the filename
    try:
        config_files.sort(key=lambda x: int(os.path.basename(x).split('_')[1].split('.')[0]))
    except Exception:
        config_files.sort() # Fallback to standard alphabetical sort if naming changes

    if not config_files:
        print(f"No configuration files found in '{CONFIG_DIR}/'.")
        print("Please run your parameter grid generation script first.")
        return

    total_configs = len(config_files)
    print(f"Found {total_configs} configurations to process. Starting the night shift...")
    
    successful_runs = []
    failed_runs = []

    # 2. Iterate and execute each configuration sequentially
    for i, config_path in enumerate(config_files, start=1):
        print("\n" + "="*60)
        print(f"[{i}/{total_configs}] STARTING EXPERIMENT: {config_path}")
        print("="*60)
        
        start_time = time.time()
        
        try:
            # subprocess.run blocks execution until the called script finishes.
            # This ensures we don't run out of GPU/CPU memory by running all at once.
            subprocess.run(
                [sys.executable, TRAIN_SCRIPT, "--config", config_path],
                check=True,
                text=True
            )
            successful_runs.append(config_path)
            
        except subprocess.CalledProcessError as e:
            failed_runs.append(config_path)
            print(f"\n[ERROR] Experiment {config_path} failed with exit code {e.returncode}.")
            print("Continuing to the next configuration...")
            
        except KeyboardInterrupt:
            print("\n[ABORT] Night shift manually interrupted by user.")
            break
            
        elapsed_time = time.time() - start_time
        print(f"[{i}/{total_configs}] FINISHED EXPERIMENT: {config_path} in {elapsed_time/60:.2f} minutes")

    # 3. Print a summary report when you check your computer in the morning
    print("\n" + "#"*40)
    print("NIGHT SHIFT COMPLETE")
    print("#"*40)
    print(f"Total Experiments:   {total_configs}")
    print(f"Successful Runs:     {len(successful_runs)}")
    print(f"Failed Runs:         {len(failed_runs)}")
    
    if failed_runs:
        print("\nThe following configurations failed and need review:")
        for failed in failed_runs:
            print(f" - {failed}")

if __name__ == "__main__":
    run_night_shift()
